//! Statement ingest — read what a bank exports, without asking anyone what it is.
//!
//! THE INSTITUTION IS INFERRED FROM THE HEADER ROW, never from a flag. Partly because a flag is one
//! more thing to get wrong, and partly for a reason particular to this crate: the less the tool has
//! to be told about someone's accounts, the less of someone's accounts has to be said out loud.
//!
//! # The one contract every profile normalises to
//!
//! **A stored amount is signed from the ACCOUNT HOLDER's point of view: negative is money leaving.**
//!
//! That is not how the exports are written, and they disagree with each other, which is exactly why
//! this has to be stated once and enforced per profile:
//!
//! - Chase writes a purchase NEGATIVE.
//! - Discover writes a purchase POSITIVE — a charge is a positive number on the card's own terms.
//! - Capital One does not sign at all: it uses separate `Debit` and `Credit` columns.
//! - Bank of America signs like Chase, but its checking and card exports carry different columns.
//!
//! Get one of these backwards and every balance built on it is wrong by twice the amount, in the
//! direction that looks like good news. So the sign rule is per profile, named, and tested.
//!
//! # Nothing is dropped quietly
//!
//! A row that cannot be read is REPORTED, never skipped. A missing transaction is a wrong balance
//! that nobody can find by looking at the balance.
use crate::money::{money, parse_minor, Currency, Minor};

/// Which export this is. `Unknown` is a first-class outcome: a header nobody recognises should say so
/// rather than be forced through the closest-looking profile.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Institution {
    Chase,
    Discover,
    CapitalOne,
    BankOfAmerica,
    Unknown,
}

impl Institution {
    pub fn name(self) -> &'static str {
        match self {
            Institution::Chase => "chase",
            Institution::Discover => "discover",
            Institution::CapitalOne => "capital-one",
            Institution::BankOfAmerica => "bank-of-america",
            Institution::Unknown => "unknown",
        }
    }

    /// Where the export button actually lives, for a person about to go and click it.
    ///
    /// UNVERIFIED like the profiles themselves — written from published layouts. A menu path that
    /// has moved costs two minutes; a wrong COLUMN costs a wrong balance, which is why the caveats
    /// live on the profiles and this is only directions.
    pub fn export_path(self) -> &'static str {
        match self {
            Institution::Discover => "Account -> Statements & Activity -> Download Transactions (CSV)",
            Institution::CapitalOne => "Account -> View Transactions -> Download -> CSV (set the date range FIRST; the default is not the one you want)",
            Institution::BankOfAmerica => "Account -> Statements & Documents -> Download -> CSV (the file opens with a summary block above the header row)",
            Institution::Chase => "Account -> Download account activity -> CSV (chequing and card are DIFFERENT layouts; download each separately)",
            Institution::Unknown => "unknown institution",
        }
    }
}

/// How an export writes its dates. DECLARED per shape, never guessed: `03/04/2026` is 4 March or
/// 3 April and the file does not say, so a reader that guessed would move every transaction by weeks
/// half the time.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DateFormat {
    /// `YYYY-MM-DD` already.
    Iso,
    /// `MM/DD/YYYY` — every US institution here except Capital One.
    MonthDayYear,
}

/// Normalise to ISO, or `None` if the text is not that date in that format.
///
/// EVERYTHING DOWNSTREAM COMPARES DATES AS STRINGS, which is only correct for ISO. A raw
/// `06/20/2026` sorts before `2026-06-01`, so a balance would never roll forward and a coverage
/// check would report the wrong side as later — both silently, both producing plausible numbers.
pub fn to_iso(raw: &str, format: DateFormat) -> Option<String> {
    let t = raw.trim();
    let (y, m, d) = match format {
        DateFormat::Iso => {
            let mut it = t.split('-');
            (it.next()?.parse::<i64>().ok()?, it.next()?.parse::<i64>().ok()?, it.next()?.parse::<i64>().ok()?)
        }
        DateFormat::MonthDayYear => {
            let mut it = t.split(['/', '-']);
            let m = it.next()?.parse::<i64>().ok()?;
            let d = it.next()?.parse::<i64>().ok()?;
            let raw_y = it.next()?;
            let mut y = raw_y.parse::<i64>().ok()?;
            if raw_y.len() == 2 {
                y += if y >= 70 { 1900 } else { 2000 };
            }
            (y, m, d)
        }
    };
    if !(1..=12).contains(&m) || !(1..=31).contains(&d) || !(1000..=9999).contains(&y) {
        return None;
    }
    Some(format!("{y:04}-{m:02}-{d:02}"))
}

/// How one export lays its columns out, and which way its amounts point.
#[derive(Debug, Clone)]
pub struct Profile {
    pub institution: Institution,
    /// Human label for the report — which export shape matched.
    pub label: &'static str,
    /// Header names that must ALL be present for this profile to match, lowercased.
    pub required: &'static [&'static str],
    pub date: &'static str,
    pub description: &'static str,
    /// A single signed amount column…
    pub amount: Option<&'static str>,
    /// …or a separate debit/credit pair, which is Capital One's shape.
    pub debit_credit: Option<(&'static str, &'static str)>,
    /// TRUE when the export writes a purchase as a POSITIVE number, so the sign must be flipped to
    /// reach "negative is money leaving". Discover is the case this exists for.
    pub charge_is_positive: bool,
    /// A RUNNING BALANCE column, where the export carries one. It is what lets `reconcile` run at
    /// all: without it there is no opening and closing to check the transactions against, and every
    /// figure downstream is standing on an unverified ledger.
    pub balance: Option<&'static str>,
    /// How this export writes its dates, so they can be normalised to ISO at read time.
    pub date_format: DateFormat,
    /// WHICH KIND OF ACCOUNT this shape belongs to.
    ///
    /// Chase and Bank of America each export a CARD and a CHEQUING layout, and they are different
    /// ACCOUNTS — one where a positive balance is money owed and one where it is money held. The
    /// inbox names files by institution alone, so without this the two would collapse onto one id
    /// and a card balance would be added to a chequing balance.
    pub account_kind: crate::account::Kind,
}

