/// One transaction, normalised.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Txn {
    /// ISO `YYYY-MM-DD`, NORMALISED HERE.
    ///
    /// This used to be "as written in the export", on the reasoning that normalising is a separate
    /// decision from reading. That was wrong once an analysis existed: everything downstream
    /// compares dates as STRINGS, which is only correct for ISO, so a raw `06/20/2026` sorted before
    /// `2026-06-01` and a balance silently never rolled forward. The shape declares its format, so
    /// this is a conversion rather than a guess.
    pub date: String,
    pub description: String,
    /// Minor units, NEGATIVE for money leaving the account holder.
    pub minor: Minor,
}

/// A row that could not be read, and why. Carried out rather than logged, so the caller decides.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rejected {
    /// 1-based line number in the file, counting the header — what a person would see in an editor.
    pub line: usize,
    pub reason: String,
}

/// The window a statement covers and the balances at each end, where the export carried a running
/// balance. The ACCOUNT and CURRENCY are absent on purpose — a row cannot know either, the same
/// reason `Txn::from_row` takes them.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PeriodBounds {
    pub opening: Minor,
    pub closing: Minor,
}

#[derive(Debug, Clone)]
pub struct Parsed {
    pub institution: Institution,
    pub profile: &'static str,
    /// The kind the matched shape says this is — carried out so a caller can offer to declare the
    /// account without re-deriving it from the label.
    pub account_kind: crate::account::Kind,
    pub txns: Vec<Txn>,
    pub rejected: Vec<Rejected>,
    /// Present only when the export carried a running balance. NONE means this file cannot be
    /// reconciled, which is a fact about the export rather than a failure.
    pub period: Option<PeriodBounds>,
}

/// The period a running-balance column asserts, SIGNED by the account's kind.
///
/// Two conversions happen here and both are load-bearing.
///
/// **The opening backs out the first row's own amount.** A running balance is stated AFTER the
/// transaction, so taking the first one as the opening double-counts the first row — and the
/// statement then fails to reconcile by exactly that amount, which reads as a missing transaction.
///
/// **The bounds are sign-normalised, because `reconcile` works in the SIGNED convention.** It checks
/// `opening + sum(txns) == closing`, and a transaction is already signed by whether money left the
/// holder. On a chequing account printed and signed coincide, which is exactly why this is easy to
/// get wrong and never notice: 1000 + (-600) = 400 either way. On a CARD they do not. A card prints
/// what you owe as a positive, so a 200 charge takes a printed 100 to a printed 300 while the signed
/// figures go -100 to -300 — and `100 + (-200) = -100`, not 300. Left printed, every card statement
/// that ever carried a running balance would fail to reconcile by twice the period's spending.
///
/// No packaged card profile carries a balance column TODAY, so this converts nothing in the shipped
/// set. It is here because the next profile someone adds must not have to know this.
pub fn period_from_running(running: &[(Minor, Minor)], kind: crate::account::Kind) -> Option<PeriodBounds> {
    let sign = |printed: Minor| crate::position::from_statement_balance(kind, money(printed, Currency::USD)).minor;
    match (running.first(), running.last()) {
        (Some((first_bal, first_amt)), Some((last_bal, _))) => {
            Some(PeriodBounds { opening: sign(first_bal - first_amt), closing: sign(*last_bal) })
        }
        _ => None,
    }
}

/// Split ONE csv line, honouring quoted fields.
///
/// A description containing a comma is not exotic — it is most of them ("SQUARE, INC"). Splitting on
/// every comma would shift every later column by one and put a date where an amount goes.
fn split_csv(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut quoted = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '"' if quoted && chars.peek() == Some(&'"') => {
                cur.push('"');
                chars.next();
            }
            '"' => quoted = !quoted,
            ',' if !quoted => out.push(std::mem::take(&mut cur)),
            c => cur.push(c),
        }
    }
    out.push(cur);
    out.into_iter().map(|s| s.trim().to_string()).collect()
}

/// The profile whose required columns are all present. Most specific first — `PROFILES` is ordered so
/// a shape with more required columns is tried before a looser one it would also satisfy.
pub fn detect(header: &[String]) -> Option<&'static Profile> {
    let have: Vec<String> = header.iter().map(|h| h.trim().to_lowercase()).collect();
    PROFILES.iter().find(|p| p.required.iter().all(|r| have.iter().any(|h| h == r)))
}

/// Parse a whole CSV export.
pub fn parse_csv(text: &str) -> Result<Parsed, String> {
    let mut lines = text.lines().enumerate().filter(|(_, l)| !l.trim().is_empty());
    let (header_line, header_raw) = lines.next().ok_or_else(|| "the file is empty".to_string())?;
    let header = split_csv(header_raw);
    let profile = detect(&header).ok_or_else(|| {
        format!(
            "no known export shape matches this header: [{}]. Add a Profile for it rather than \
             forcing it through the closest one — a mis-mapped column reads as a plausible number.",
            header.join(", ")
        )
    })?;

    let col = |name: &str| header.iter().position(|h| h.trim().eq_ignore_ascii_case(name));
    let (di, ci) = (col(profile.date), col(profile.description));
    let (Some(di), Some(ci)) = (di, ci) else {
        return Err(format!("{}: the header lost a column between detection and read", profile.label));
    };

    let mut txns = Vec::new();
    let mut rejected = Vec::new();
    // (running balance, that row's own amount) in file order, for the period derivation below.
    let mut running: Vec<(Minor, Minor)> = Vec::new();
    let balance_col = profile.balance.and_then(col);
    for (idx, raw) in lines {
        let line = idx + 1; // 1-based, as an editor shows it
        let f = split_csv(raw);
        let get = |i: usize| f.get(i).map(String::as_str).unwrap_or("").trim();
        if f.len() < header.len() {
            rejected.push(Rejected { line, reason: format!("{} columns, expected {}", f.len(), header.len()) });
            continue;
        }
        let minor = match (profile.amount, profile.debit_credit) {
            (Some(a), _) => {
                let Some(ai) = col(a) else {
                    rejected.push(Rejected { line, reason: format!("no `{a}` column") });
                    continue;
                };
                match parse_minor(get(ai)) {
                    Ok(v) => {
                        // Discover's convention: a charge is written positive. Flip so the store's
                        // rule holds — negative is money leaving.
                        if profile.charge_is_positive { -v } else { v }
                    }
                    Err(e) => {
                        rejected.push(Rejected { line, reason: e });
                        continue;
                    }
                }
            }
            (None, Some((d, c))) => {
                // Capital One: exactly one of the two carries a value. Both, or neither, is a row
                // this parser does not understand — and guessing which to believe would be inventing
                // a transaction.
                let (Some(dbi), Some(cri)) = (col(d), col(c)) else {
                    rejected.push(Rejected { line, reason: format!("no `{d}`/`{c}` columns") });
                    continue;
                };
                let (dv, cv) = (get(dbi), get(cri));
                match (dv.is_empty(), cv.is_empty()) {
                    (false, true) => match parse_minor(dv) {
                        Ok(v) => -v.abs(), // a debit is money leaving
                        Err(e) => { rejected.push(Rejected { line, reason: e }); continue; }
                    },
                    (true, false) => match parse_minor(cv) {
                        Ok(v) => v.abs(), // a credit is money arriving
                        Err(e) => { rejected.push(Rejected { line, reason: e }); continue; }
                    },
                    (true, true) => { rejected.push(Rejected { line, reason: "neither debit nor credit has a value".into() }); continue; }
                    (false, false) => { rejected.push(Rejected { line, reason: "both debit and credit have values".into() }); continue; }
                }
            }
            (None, None) => return Err(format!("{}: profile declares no amount column", profile.label)),
        };
        let Some(date) = to_iso(get(di), profile.date_format) else {
            rejected.push(Rejected { line, reason: format!("`{}` is not a date this shape writes", get(di)) });
            continue;
        };
        if date.is_empty() {
            rejected.push(Rejected { line, reason: "no date".into() });
            continue;
        }
        if let Some(bi) = balance_col {
            if let Ok(b) = parse_minor(get(bi)) {
                running.push((b, minor));
            }
        }
        txns.push(Txn { date, description: get(ci).to_string(), minor });
    }
    let _ = header_line;

    let period = period_from_running(&running, profile.account_kind);
    Ok(Parsed { institution: profile.institution, profile: profile.label, account_kind: profile.account_kind, txns, rejected, period })
}

/// The account id a matched shape suggests.
///
/// THE INBOX NAMES FILES BY INSTITUTION ALONE, and Chase and Bank of America each export a card and
/// a chequing layout. `chase-june.csv` and `chase-checking-june.csv` both read as "chase", so
/// without a wider id the two would collapse onto one account — and a card balance, where positive
/// means OWED, would be added to a chequing balance, where it means HELD. The profile knows which
/// shape it matched, so the id comes from there rather than from the filename.
pub fn suggested_account_id(p: &Parsed) -> String {
    let kind = p.account_kind.as_str();
    // A chequing account at an institution that exports only one shape needs no suffix; the two
    // that export both do.
    let ambiguous = PROFILES.iter().filter(|x| x.institution == p.institution).count() > 1;
    if ambiguous {
        format!("{}-{}", p.institution.name(), kind)
    } else {
        p.institution.name().to_string()
    }
}

#[cfg(test)]
mod tests {

    #[test]
    fn a_running_balance_becomes_a_period_that_actually_reconciles() {
        // Reference taken by running `ingest.ts` on this exact CSV: opening 100000, closing 40000.
        let csv = "Date,Description,Amount,Running Bal.\n\
06/03/2026,\"OPENING SPEND\",-100.00,\"900.00\"\n\
06/10/2026,\"PAY\",1000.00,\"1,900.00\"\n\
06/20/2026,\"RENT\",-1500.00,\"400.00\"\n";
        let p = parse_csv(csv).unwrap();
        let b = p.period.expect("a running balance should produce a period");
        assert_eq!(b.opening, 100_000, "the opening backs out the first row's own amount");
        assert_eq!(b.closing, 40_000);

        // And the whole point: it reconciles. If the sign, the amounts or the opening derivation
        // were wrong, this would not balance.
        let txns: Vec<crate::txn::Txn> = p
            .txns
            .iter()
            .map(|r| crate::txn::Txn::from_row(r, "checking", crate::money::Currency::USD))
            .collect();
        let period = crate::reconcile::usd_period("checking", &txns[0].date, &txns[txns.len() - 1].date, b.opening, b.closing);
        let rec = crate::reconcile::reconcile(&txns, &[period]);
        assert!(rec.ok, "{:?}", rec.problems);
        assert!(rec.ledger.is_some());
    }

    #[test]
    fn taking_the_running_balance_as_the_opening_would_double_count_the_first_row() {
        // Stated AFTER the transaction. Using it directly leaves the statement out by exactly that
        // first amount, which reads as a missing transaction rather than as a derivation bug.
        let csv = "Date,Description,Amount,Running Bal.\n06/03/2026,X,-100.00,\"900.00\"\n";
        let b = parse_csv(csv).unwrap().period.unwrap();
        assert_eq!(b.opening, 100_000);
        assert_ne!(b.opening, 90_000, "90000 is the running balance itself, not the opening");
    }

    #[test]
    fn a_card_periods_bounds_come_back_signed_so_reconcile_can_use_them() {
        use crate::account::Kind;
        // A card printing 100 owed, then 300 owed after a 200 charge. The rows are (running, amount)
        // in the PRINTED convention the export uses; the amount is already signed, as every Txn is.
        let running = vec![(10_000, 0), (30_000, -20_000)];
        let b = super::period_from_running(&running, Kind::Credit).expect("two rows is a period");
        // Printed 100 owed is -10000 to net worth, printed 300 owed is -30000.
        assert_eq!(b.opening, -10_000, "the opening must be NEGATED for a debt account");
        assert_eq!(b.closing, -30_000, "the closing must be NEGATED for a debt account");
        // And it reconciles: -10000 + (-20000) = -30000. Left printed it would not.
        assert_eq!(b.opening + (-20_000), b.closing, "signed bounds are what makes the arithmetic close");
    }

    #[test]
    fn a_chequing_periods_bounds_are_unchanged_because_printed_and_signed_agree_there() {
        use crate::account::Kind;
        let running = vec![(90_000, -10_000), (40_000, -30_000)];
        let b = super::period_from_running(&running, Kind::Checking).expect("two rows is a period");
        assert_eq!(b.opening, 100_000);
        assert_eq!(b.closing, 40_000);
    }

    #[test]
    fn a_card_export_carries_no_running_balance_and_says_so_by_absence() {
        // A fact about the export, not a failure: a card statement simply does not print one, so
        // that file cannot be reconciled and the ledger built from it is honestly unverified.
        let p = parse_csv("Trans. Date,Description,Amount\n06/03/2026,X,10.00\n").unwrap();
        assert!(p.period.is_none());
        for prof in PROFILES {
            assert_eq!(prof.balance.is_some(), prof.account_kind == crate::account::Kind::Checking, "{}", prof.label);
        }
    }

    #[test]
    fn every_parsed_date_comes_out_as_iso_whatever_the_export_wrote() {
        // THE BUG THIS EXISTS FOR, found by running the thing rather than by any of 152 tests: the
        // parser kept dates as written, and everything downstream compares them as STRINGS. A raw
        // `06/20/2026` sorts BEFORE `2026-06-01`, so a balance never rolled forward and a coverage
        // check reported the wrong side as later — both silently, both plausible.
        let discover = parse_csv("Trans. Date,Description,Amount\n06/20/2026,X,10.00\n").unwrap();
        assert_eq!(discover.txns[0].date, "2026-06-20");
        let cap = parse_csv("Transaction Date,Description,Debit,Credit\n2026-06-20,X,10.00,\n").unwrap();
        assert_eq!(cap.txns[0].date, "2026-06-20");
        // And ISO is what makes a string comparison correct at all.
        assert!("2026-06-01" < "2026-06-20");
    }

    #[test]
    fn every_profile_declares_how_it_writes_dates() {
        // Nothing guesses. `03/04/2026` is 4 March or 3 April and the file does not say.
        for p in PROFILES {
            let sample = match p.date_format {
                DateFormat::Iso => "2026-03-04",
                DateFormat::MonthDayYear => "03/04/2026",
            };
            assert_eq!(to_iso(sample, p.date_format).as_deref(), Some("2026-03-04"), "{}", p.label);
        }
    }

    #[test]
    fn a_date_the_shape_cannot_write_is_rejected_rather_than_kept_raw() {
        let r = parse_csv("Trans. Date,Description,Amount\n2026-06-20,X,10.00\n").unwrap();
        assert_eq!(r.txns.len(), 0);
        assert_eq!(r.rejected.len(), 1);
        assert!(r.rejected[0].reason.contains("not a date this shape writes"), "{}", r.rejected[0].reason);
    }

    #[test]
    fn to_iso_refuses_a_month_or_day_that_cannot_exist() {
        assert_eq!(to_iso("13/01/2026", DateFormat::MonthDayYear), None);
        assert_eq!(to_iso("06/32/2026", DateFormat::MonthDayYear), None);
        assert_eq!(to_iso("not a date", DateFormat::MonthDayYear), None);
        // Two-digit years, which several exports still emit.
        assert_eq!(to_iso("06/20/26", DateFormat::MonthDayYear).as_deref(), Some("2026-06-20"));
    }

    #[test]
    fn every_profile_declares_which_kind_of_account_it_is() {
        // A card and a chequing export are different ACCOUNTS: positive means OWED in one and HELD
