        // suggested ids would collide and a card balance would be summed with a chequing balance.
        for inst in [Institution::Chase, Institution::BankOfAmerica] {
            let kinds: Vec<_> = PROFILES.iter().filter(|p| p.institution == inst).map(|p| p.account_kind).collect();
            assert_eq!(kinds.len(), 2, "{}", inst.name());
