        // strings would silently route a card export through the chequing profile — which parses
        // without complaint and produces a balance with the wrong sign convention behind it.
        let card = parse_csv("Transaction Date,Post Date,Description,Amount\n06/03/2026,06/04/2026,X,-10.00\n").unwrap();
        let chq = parse_csv("Posting Date,Description,Amount,Balance\n06/03/2026,X,-10.00,100.00\n").unwrap();
        assert_eq!(card.profile, "chase card");
        assert_eq!(chq.profile, "chase checking");
        assert_eq!(card.account_kind, crate::account::Kind::Credit);
        assert_eq!(chq.account_kind, crate::account::Kind::Checking);
